user_prompt_template:
DOCUMENT TYPE: {doc_type}

Analyze this document image for fraud indicators. Return STRICT JSON only with this structure:

{
  "overall_assessment": {
    "authentic": true/false,
    "confidence": 0.0 to 1.0,
    "summary": "Brief summary of findings"
  },
  "digital_forensics": {
    "pixel_integrity": "Check for cloning artifacts, copy-paste痕迹, inconsistent noise patterns, compression anomalies across the image",
    "edge_detection": "Analyze borders and edges of photos, stamps, signatures for cut marks, feathering, or unnatural transitions",
    "lighting_consistency": "Check that lighting direction and intensity are consistent across all elements of the document",
    "background_analysis": "Check for background replacement, unnatural color gradients, texture mismatches"
  },
  "physical_security_features": {
    "watermark": "visible/not visible/authentic/suspicious — describe what you see",
    "hologram": "present/absent — describe tilt behavior, color shifts, depth",
    "microprinting": "visible/not visible — check for legible microtext under magnification",
    "embossing": "present/absent — describe tactile evidence if visible",
    "security_pattern": "guilloche/fine-lines/none — check for consistent pattern, no breaks or misalignment"
  },
  "signature_analysis": {
    "signature_present": true/false,
    "is_original_ink": true/false/suspicious,
    "stamped_or_printed": true/false,
    "anomalies": "List any: uniform pixel color suggesting photocopy, trembling lines suggesting tracing, unnatural smoothness"
  },
  "font_analysis": {
    "font_consistency": "consistent/inconsistent",
    "anomalies": "Describe: mixed typefaces, irregular kerning, wrong font for official document, bold/regular mixing, character shape inconsistencies"
  },
  "document_integrity": {
    "date_validity": "Check that dates are logical, not future-dated (unless expiry), properly formatted, chronological order maintained",
    "id_numbers_valid": true/false,
    "photo_integrity": "Check photo for replacement, different lighting, pixel boundaries, compression mismatch between photo and background",
    "cross_reference_consistency": "Verify internal document consistency — do all fields agree with each other?"
  },
  "fraud_indicators": [
    "List EVERY suspected issue with specific evidence. Empty array ONLY if document is 100% forensically clean."
  ],
  "recommended_action": "approve/reject/manual_review"
}

RULES:
- Be exhaustive — list every potential fraud indicator, no matter how minor
- A single forgery indicator with high confidence justifies rejection
- If image quality prevents full analysis, set confidence <= 0.5 and recommend manual_review
- Do NOT let a document pass just because "it looks OK at first glance" — verify every security feature
- Military recruitment forgery is a serious offense — false negatives are far worse than false positives
